    C c;

    constructor(C _c) { c = _c; }

    function run(address from, address[] memory _tos, uint v, address target) public payable {
        bool reverted;
        bool ret;

        if (_tos.length == 0) {
            try c.transfer(from, target, _tos, v) { reverted = false; } catch { reverted = true; }
            assert(reverted);
