contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(address from, address[] memory _tos, uint v) public payable {
        require(_tos.length > 0);
        bool reverted;
        try c.transfer(from, address(this), _tos, v) {
            reverted = false;
        } catch {
            reverted = true;
        }
        if (reverted) {
            assert(allEqualZero(_tos));
        } else {
            assert(true);
        }
    }

    function allEqualZero(address[] memory arr) internal pure returns (bool) {
        for (uint i = 0; i < arr.length; i++) {
            if (arr[i] != address(0)) return false;
        }
        return true;
    }

    receive() external payable {}
}

